"""Deterministic document generation from the structured state (no LLM involved)."""
from app.schemas import WishesState
from app.state import get_value, is_complete, missing_fields, unconfirmed_fields

BANNER = (
    "*** FICTIONAL DOCUMENT - NOT LEGAL ADVICE ***\n"
    "This draft was generated by a demonstration application. It has no legal effect."
)
NOT_YET = "[NOT YET PROVIDED]"
SKIPPED = "[NOT PROVIDED]"


def _wrap(state: WishesState, path: str, text: str | None) -> str:
    """Render a value according to its status, never presenting unconfirmed data as fact."""
    status = state.status.get(path)
    if status == "skipped":
        return SKIPPED
    if text is None:
        return NOT_YET
    return f"[TO CONFIRM: {text}]" if status == "unconfirmed" else text


def _scalar(state: WishesState, path: str) -> str:
    return _wrap(state, path, get_value(state.data, path))


def _yes_no(state: WishesState, path: str, yes: str, no: str) -> str:
    value = get_value(state.data, path)
    return _wrap(state, path, None if value is None else (yes if value else no))


def _items(state: WishesState, path: str, none_text: str) -> list[str]:
    value = get_value(state.data, path)
    status = state.status.get(path)
    if status == "skipped":
        return [SKIPPED]
    if value is None:
        return [NOT_YET]
    if not value:
        return [_wrap(state, path, none_text)]
    lines = [f"  {i}. {item}" for i, item in enumerate(value, 1)]
    return lines + (["  [TO CONFIRM: the list above]"] if status == "unconfirmed" else [])


def render_document(state: WishesState) -> str:
    d = state.data
    lines = ["PERSONAL WISHES DOCUMENT (DRAFT)", "", BANNER, "", "1. ABOUT ME",
             f"I, {_scalar(state, 'full_name')}, of {_scalar(state, 'home_address')}, "
             "set out the wishes below.", "", "2. SCOPE",
             _yes_no(state, "covers_worldwide_assets",
                     "This document is intended to cover my assets worldwide.",
                     "This document is not intended to cover assets worldwide."),
             "", "3. MY CHILDREN",
             _yes_no(state, "has_children", "I have children.", "I do not have any children.")]
    if d.has_children:
        lines += ["My children are:"] + _items(state, "children_names", "None.")
    lines += ["", "4. MY EXECUTOR",
              f"I appoint {_scalar(state, 'executor.name')}, my {_scalar(state, 'executor.relationship')}, "
              "to act as my executor.", "", "5. SPECIFIC GIFTS"]
    lines += _items(state, "specific_gifts", "I have no specific gifts to leave.")
    lines += ["", "6. ADDITIONAL WISHES"]
    lines += _items(state, "additional_wishes", "I have no additional wishes.")
    todo = len(missing_fields(state)) + len(unconfirmed_fields(state))
    status = ("Draft status: complete and ready for review." if is_complete(state)
              else f"Draft status: incomplete - {todo} item(s) still need your input.")
    return "\n".join(lines + ["", "-" * 48, status, "Fictional document - not legal advice."])
